import {z} from 'zod';
import {ids,revision,sha256,gitCommit,timestamp,opaqueKey} from './primitives.js';
import {deliveryDataPlan} from './delivery.js';

export const acceptanceCandidateBasis=z.strictObject({candidateRevision:revision,manifestHash:sha256,reviewHash:sha256,expectedAcceptedReleaseId:ids.release.nullable(),dataPlanHash:sha256});
export const beginAcceptanceInput=acceptanceCandidateBasis.extend({policyHash:sha256});
export const confirmAcceptanceReplacementInput=acceptanceCandidateBasis.extend({decisionId:ids.decision,confirmation:z.literal('REPLACE_ACCEPTED_DATA')});
export const closeUnsentAcceptanceInput=z.strictObject({requestHash:sha256});
export const abortAcceptanceInput=z.strictObject({requestHash:sha256,expectedPreparationRevision:revision,reason:z.string().trim().min(1).max(2000),confirmation:z.literal('ABORT_ACCEPTANCE_PREPARATION')});
export const acceptCandidateInput=acceptanceCandidateBasis.extend({runId:ids.run,preparationOperationId:ids.operation,requestHash:sha256,expectedPreparationRevision:revision,expectedObservationSequence:revision,proofHash:sha256,confirmation:z.literal('ACCEPT_RELEASE')});
export const acceptanceBasisView=acceptanceCandidateBasis.extend({projectId:ids.project,runId:ids.run,candidateId:ids.candidate,codeCommit:gitCommit,dataPlan:deliveryDataPlan,currentAcceptedReleaseId:ids.release.nullable(),resourceRevision:revision,qualification:z.enum(['CURRENT','STALE']),configured:z.boolean(),policyHash:sha256.nullable(),replacementConfirmed:z.boolean(),blockedByPreparationOperationId:ids.operation.nullable(),canManage:z.boolean(),canPrepare:z.boolean(),canConfirmReplacement:z.boolean(),reason:z.enum(['NOT_OWNER','REVIEW_REQUIRED','CANDIDATE_STALE','SOURCE_CHANGED','BACKEND_UNAVAILABLE','REPLACEMENT_CONFIRMATION_REQUIRED','PREPARATION_UNRESOLVED','EFFECT_UNRESOLVED']).nullable()});
export const acceptancePreparationView=z.strictObject({operationId:ids.operation,runId:ids.run,candidateId:ids.candidate,releaseId:ids.release,requestHash:sha256,revision:revision,state:z.enum(['PREPARED','SENT','UNKNOWN','FAILED']),resolution:z.enum(['UNRESOLVED','UNSENT_FAILED','COMMITTED','ABORTING','ABORTED']),qualification:z.enum(['CURRENT','STALE']),basis:acceptanceCandidateBasis,createdAt:timestamp,updatedAt:timestamp,acceptanceOperationId:ids.operation.nullable(),readiness:z.strictObject({state:z.enum(['UNPREPARED','READY','UNAVAILABLE','STALE']),sequence:z.number().int().nonnegative().safe(),proofHash:sha256.nullable(),checkedAt:timestamp.nullable()}),resourceRevision:revision,canCommit:z.boolean(),canCloseUnsent:z.boolean(),canAbort:z.boolean()});
export const acceptancePreparationList=z.strictObject({items:z.array(z.strictObject({sequence:revision,preparation:acceptancePreparationView})).max(100),nextSequence:revision.nullable()});
export const acceptanceReplacementReceipt=z.strictObject({decisionId:ids.decision,operationId:ids.operation});
export const acceptanceAbortReceipt=z.strictObject({operationId:ids.operation,preparationOperationId:ids.operation,decisionHash:sha256,reason:z.string().min(1).max(2000),decidedAt:timestamp,decisionState:z.literal('RECORDED')});
// Public fixed receipt fields only; private preparedProof and dataset paths never cross HTTP.
export const acceptedReleaseView=z.strictObject({releaseId:ids.release,projectId:ids.project,runId:ids.run,candidateId:ids.candidate,candidateRevision:revision,manifestHash:sha256,reviewHash:sha256,preparationOperationId:ids.operation,acceptanceOperationId:ids.operation,requestHash:sha256,proofHash:sha256,datasetId:ids.dataset,previousReleaseId:ids.release.nullable(),acceptedBy:opaqueKey,acceptedAt:timestamp,acceptanceState:z.literal('ACCEPTED'),publicationState:z.literal('PENDING')});
export const acceptanceCommitReceipt=z.strictObject({operationId:ids.operation,status:z.literal('SUCCEEDED'),result:acceptedReleaseView,links:z.strictObject({preparation:z.string().regex(/^\/api\/v1\/runs\/run_[A-Za-z0-9_-]+\/candidates\/candidate_[A-Za-z0-9_-]+\/acceptance\/preparations\/op_[A-Za-z0-9_-]+$/)})});
